void myfree(void *ptr);', 'mode' => 'solution', 'hint' => 'Question d’examen de Stanford : rédige ta réponse, puis la correction officielle de Stanford s’affiche.', 'explanation' => 'Corrigé officiel de Stanford : void myfree(void *ptr) { if (ptr == NULL) return; headerT *header = (headerT *)ptr - 1; // past end or before beginning – include offset padding if ((char *)header >= ((char*)heapStart + heapSize)) return; if ((char *)header < ((char*)heapStart + 4)) return; if (!is_allocated(header)) return; int mask = -1 << 2; header->payloadsz &= mask; // clear out alloc/realloc bits // clear footer int *footer = (int *)((char *)header + get_size(header) + sizeof(headerT)); *footer = header->payloadsz; // update free list header->next = free_list; header->prev = NULL; if (free_list != NULL) free_list->prev = header; free_list = header; }', 'source' => 'Stanford University, CS107 Data Structures — practice final exams 1, 2 and 3, with the official solutions (Stanford)', 'licence' => 'Aucune licence explicite publiee sur ces pages', 'xp' => 20),
							array('question' => '[Stanford — question d’examen, en anglais]  Problem 5 (Heap Allocator) — partie (f)
(10pts) Write a simple implementation of myrealloc given this design. Your myrealloc
should do the following:
> •
Assume ptr points to a valid, allocated block’s payload. If the realloc size is less than or equal to the current payload size, do nothing and return ptr . (you do not need to change the value of the reallocated bit in this case)
> •
If the block has previously been reallocated, proceed as if the request is for double the actual request size, in anticipation that there may be future myrealloc calls that will now be very fast so long as they fit within this preemptive doubling.
> •
Perform the realloc by calling myfree and mymalloc (do not manually do any of the work for this). Be sure to copy the caller’s data for them. Even though you are the heap allocator, order these operations in a way that respects the usual convention that one does not access freed memory.
> •
Be sure that the allocated and reallocated flag bits are set appropriately to show this was reallocated.
> •
# This simple version does not attempt to look for free blocks to the right to expand into, nor does coalesce or other advanced features.
void *myrealloc(void *ptr, size_t size); 13', 'mode' => 'solution', 'hint' => 'Question d’examen de Stanford : rédige ta réponse, puis la correction officielle de Stanford s’affiche.', 'explanation' => 'Corrigé officiel de Stanford : void *myrealloc(void *ptr, size_t size) { headerT *header = (headerT *)ptr - 1; int cursz = get_size(header); if (size <= cursz) return ptr; if (is_reallocated(header)) size *= 2; void *block = mymalloc(size); if (!block) return NULL; memcpy(block, ptr, cursz); myfree(ptr); int mask = 0x2; // rewind to header, mark realloc header = (headerT *)block - 1; header->payloadsz |= mask; // mark footer realloc and make new header int *footer = (int *)((char *)header + sizeof(headerT) + get_size(header)); *footer |= mask; return block; }7', 'source' => 'Stanford University, CS107 Data Structures — practice final exams 1, 2 and 3, with the official solutions (Stanford)', 'licence' => 'Aucune licence explicite publiee sur ces pages', 'xp' => 20),
